const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `[Сгруппировать факты по полям] Ожидался 1 item, получено: ${items.length}`
  );
}

const input = items[0].json;


// ============================================================
// 1. Каталог tender_fields_v1
// ============================================================

const FIELD_KEYS = [
  'procurement_subject',
  'nm_price_with_vat',
  'platform',
  'procedure_type',
  'application_deadline',
  'application_review_date',
  'results_date',
  'customer',
  'customer_contacts',
  'participation_cost',
  'participation_guarantee',
  'evaluation_criteria',
  'delivery_term',
  'payment_terms',
  'special_account_or_treasury',
  'bank_support',
  'government_contract',
  'rebidding',
  'national_regime',
  'advance_contract_guarantee',
  'warranty_obligations_guarantee',
  'licenses_certificates',
  'required_official_certificates',
  'similar_supply_experience',
  'analog_allowed',
  'analog_definition',
  'application_documents',
];

const allowedFieldKeys =
  new Set(FIELD_KEYS);


const facts =
  Array.isArray(input.facts)
    ? input.facts
    : [];

const documents =
  Array.isArray(input.documents)
    ? input.documents
    : [];


// ============================================================
// 2. Создаём все 27 групп заранее
// ============================================================

const groups =
  new Map(
    FIELD_KEYS.map(
      fieldKey => [
        fieldKey,
        [],
      ]
    )
  );


// ============================================================
// 3. Раскладываем candidate facts по field_key
// ============================================================

for (const fact of facts) {
  const fieldKey =
    fact?.field_key;

  if (
    typeof fieldKey !== 'string' ||
    !allowedFieldKeys.has(fieldKey)
  ) {
    throw new Error(
      `[Сгруппировать факты по полям] Неизвестный field_key: ${fieldKey}`
    );
  }

  groups
    .get(fieldKey)
    .push(fact);
}


// ============================================================
// 4. Один output item = одно поле каталога
// ============================================================

return FIELD_KEYS.map(
  (
    fieldKey,
    fieldIndex
  ) => {
    const candidates =
      groups.get(fieldKey);

    const confirmedCount =
      candidates.filter(
        fact =>
          fact.validator_verdict ===
          'confirmed'
      ).length;

    const requiresReviewCount =
      candidates.filter(
        fact =>
          fact.validator_verdict ===
          'requires_review'
      ).length;


    const documentIds =
      [
        ...new Set(
          candidates
            .map(
              fact =>
                fact.document_id
            )
            .filter(Boolean)
        ),
      ];


    const sourceDocuments =
      documents
        .filter(
          document =>
            documentIds.includes(
              document.document_id
            )
        )
        .map(
          document => ({
            document_id:
              document.document_id,

            document_index:
              document.document_index,

            file_name:
              document.file_name,

            file_extension:
              document.file_extension,
          })
        );


    return {
      json: {
        analysis_run_id:
          input.analysis_run_id,

        field_catalog_version:
          'tender_fields_v1',

        field_index:
          fieldIndex + 1,

        field_key:
          fieldKey,

        has_candidates:
          candidates.length > 0,

        candidates_count:
          candidates.length,

        confirmed_count:
          confirmedCount,

        requires_review_count:
          requiresReviewCount,

        source_documents_count:
          sourceDocuments.length,

        source_documents:
          sourceDocuments,

        candidates,
      },
    };
  }
);

const input = $json;

if (!input.analysis_run_id) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] Нет field_key'
  );
}

if (!Array.isArray(input.candidates)) {
  throw new Error(
    '[Подготовить запрос Semantic Aggregator] candidates должен быть массивом'
  );
}


// ============================================================
// Правила смысловой агрегации по field_key.
// Сейчас отлаживаем:
// - procurement_subject
// - delivery_term
