  Object.values(
    request.tender_metadata ?? {}
  )
    .filter(
      value =>
        value !== null &&
        value !== undefined &&
        String(value).trim() !== ''
    )
    .map(normalize);


// Также сохраняем semantic_block_id,
// на котором был основан исходный кандидат.
const existingEvidenceBlockIds =
  new Set(
    (request.existing_candidates ?? [])
      .flatMap(
        candidate =>
          Array.isArray(candidate.evidence)
            ? candidate.evidence
            : []
      )
      .map(
        evidence =>
          evidence.semantic_block_id
      )
      .filter(Boolean)
  );


