//   чтобы не потерять заголовок или пояснение.
// ============================================================

const compactUnits = [];

for (const unit of input.context_units) {

  const segments =
    Array.isArray(unit.ai_segments)
      ? unit.ai_segments
      : [];

  const selectedIndexes =
    new Set();

  const segmentMatches =
    new Map();


  for (
    let index = 0;
    index < segments.length;
    index++
  ) {
    const segment =
      segments[index];

    const text =
      normalize(segment.text);

    const matchedSearchTerms =
      searchTerms.filter(
        term =>
          text.includes(term)
      );

    const matchedMetadataTerms =
      metadataTerms.filter(
        term =>
          text.includes(term)
      );

    const isExistingEvidence =
      existingEvidenceBlockIds.has(
        segment.semantic_block_id
      );

    const isMatched =
      matchedSearchTerms.length > 0 ||
      matchedMetadataTerms.length > 0 ||
      isExistingEvidence;


    if (!isMatched) {
      continue;
    }


    selectedIndexes.add(index);

    // Добавляем ближайший контекст.
    if (index > 0) {
      selectedIndexes.add(
        index - 1
      );
    }

    if (index < segments.length - 1) {
      selectedIndexes.add(
        index + 1
      );
    }


    segmentMatches.set(
      index,
      {
        matched_search_terms:
          matchedSearchTerms,

        matched_metadata_terms:
          matchedMetadataTerms,

        is_existing_evidence:
          isExistingEvidence,
      }
    );
  }


  // Если unit был найден retrieval,
  // но ни один отдельный блок не удалось выбрать,
  // не отправляем весь unit автоматически.
  if (selectedIndexes.size === 0) {
    continue;
  }


  const selectedSegments =
    [...selectedIndexes]
      .sort((a, b) => a - b)
      .map(index => {

        const segment =
          segments[index];

        const match =
          segmentMatches.get(index);

        return {
          semantic_block_id:
            segment.semantic_block_id,

          type:
            segment.type ?? null,

          role:
            segment.role ?? null,

          scope:
            segment.scope ?? null,

          text:
            segment.text ?? '',

          direct_match:
            Boolean(match),

          matched_search_terms:
            match?.matched_search_terms ?? [],

          matched_metadata_terms:
            match?.matched_metadata_terms ?? [],

          is_existing_evidence:
            match?.is_existing_evidence ?? false,
        };
      });


