СТРУКТУРИРОВАННЫЕ METADATA ЗАКУПКИ:

${JSON.stringify(
  input.tender_metadata ?? {},
  null,
  2
)}


СУЩЕСТВУЮЩИЕ КАНДИДАТЫ:

${JSON.stringify(
  existingCandidates,
  null,
  2
)}


ДОПОЛНИТЕЛЬНЫЙ КОНТЕКСТ ИЗ ДОКУМЕНТОВ:

${JSON.stringify(
  contextForAi,
  null,
  2
)}


ЗАДАЧА:

Повторно проверь только поле nm_price_with_vat.

Нужно определить, появились ли после получения дополнительного
контекста достаточные доказательства для нового надёжного кандидата.

Не подтверждай значение только потому, что несколько источников
содержат одинаковое число.

Отдельно учитывай смысл max_price и отдельно сведения об НДС.

Верни результат строго по targeted_recheck_extractor_v1.
`.trim();


// ============================================================
// 7. Allow-list для будущей детерминированной проверки
// ============================================================

const allowedSemanticBlocks =
  contextForAi.flatMap(unit =>
    unit.segments.map(segment => ({
      analysis_unit_id:
        unit.analysis_unit_id,

      semantic_block_id:
        segment.semantic_block_id,

      text:
        segment.text,
    }))
  );


// ============================================================
// 8. Output
// ============================================================

return {
  json: {
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,

    recheck_attempt:
      input.recheck_attempt,

    system_prompt:
      systemPrompt,

    user_prompt:
      userPrompt,

    allowed_semantic_blocks:
      allowedSemanticBlocks,

    allowed_metadata:
      input.tender_metadata ?? {},

    original_aggregation:
      input.original_aggregation,

    existing_candidates:
      existingCandidates,

    recheck_context:
      contextForAi,
  },
};

