parameters.jsCode:
const aiResponse = $json;

const source =
  $('Подготовить запрос AI Targeted Recheck').item.json;


// ============================================================
// 1. Техническая проверка ответа DeepSeek
// ============================================================

const choice =
  aiResponse?.choices?.[0];

if (!choice) {
  throw new Error(
    '[Targeted Recheck Evidence Validator] Нет choices[0]'
  );
}

if (choice.finish_reason !== 'stop') {
  throw new Error(
    `[Targeted Recheck Evidence Validator] Некорректный finish_reason=${choice.finish_reason}`
  );
}

const content =
  choice?.message?.content;

if (
  typeof content !== 'string' ||
  !content.trim()
) {
  throw new Error(
    '[Targeted Recheck Evidence Validator] message.content пуст'
  );
}


// ============================================================
// 2. Парсим JSON модели
// ============================================================

let result;

try {
  result =
    JSON.parse(content);
} catch (error) {
  throw new Error(
    `[Targeted Recheck Evidence Validator] Невалидный JSON: ${error.message}`
  );
}


// ============================================================
// 3. Разрешённые значения
// ============================================================

const ALLOWED_OUTCOMES =
  new Set([
    'candidate_found',
    'insufficient_evidence',
  ]);

const ALLOWED_STATUSES =
  new Set([
    'found',
    'requires_review',
  ]);

const ALLOWED_REVIEW_CODES =
  new Set([
    'insufficient_evidence',
    'ambiguous_scope',
    'conflicting_evidence',
    'template_or_placeholder',
    'other',
  ]);


// ============================================================
// 4. Общий контракт ответа
// ============================================================

if (
  result.schema_version !==
  'targeted_recheck_extractor_v1'
) {
  throw new Error(
    `[Targeted Recheck Evidence Validator] Некорректный schema_version=${result.schema_version}`
  );
}

if (
  result.field_key !==
  source.field_key
) {
  throw new Error(
    `[Targeted Recheck Evidence Validator] field_key изменён: ожидался ${source.field_key}, получен ${result.field_key}`
  );
}

if (
  !ALLOWED_OUTCOMES.has(
    result.recheck_outcome
  )
) {
  throw new Error(
    `[Targeted Recheck Evidence Validator] Недопустимый recheck_outcome=${result.recheck_outcome}`
  );
}

if (!Array.isArray(result.candidates)) {
  throw new Error(
    '[Targeted Recheck Evidence Validator] candidates должен быть массивом'
  );
}


// ============================================================
// 5. Создаём allow-list semantic blocks
// ============================================================

const allowedBlocks =
  Array.isArray(source.allowed_semantic_blocks)
    ? source.allowed_semantic_blocks
    : [];

const blockMap =
  new Map();

for (const block of allowedBlocks) {

  if (
    !block.analysis_unit_id ||
    !block.semantic_block_id
  ) {
    continue;
  }

  const key =
    `${block.analysis_unit_id}\u0000${block.semantic_block_id}`;

  blockMap.set(
    key,
    String(block.text ?? '')
  );
}


// ============================================================
// 6. Metadata allow-list
// ============================================================

const allowedMetadata =
  source.allowed_metadata ?? {};


// ============================================================
// 7. Нормализация только пробелов
// ============================================================

function normalizeWhitespace(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}


// ============================================================
// 8. Проверяем режим insufficient_evidence
// ============================================================

if (
  result.recheck_outcome ===
  'insufficient_evidence'
) {

  if (result.candidates.length !== 0) {
    throw new Error(
      '[Targeted Recheck Evidence Validator] При insufficient_evidence candidates должен быть пуст'
    );
  }

  if (
    typeof result.recheck_note !== 'string' ||
    !result.recheck_note.trim()
  ) {
    throw new Error(
      '[Targeted Recheck Evidence Validator] При insufficient_evidence нужен recheck_note'
    );
  }
}


// ============================================================
// 9. Проверяем режим candidate_found
// ============================================================

if (
  result.recheck_outcome ===
  'candidate_found'
) {

  if (result.candidates.length === 0) {
    throw new Error(
      '[Targeted Recheck Evidence Validator] candidate_found без candidates'
    );
  }
}


// ============================================================
// 10. Проверяем каждого кандидата
// ============================================================

const usedCandidateIndexes =
  new Set();

const verifiedCandidates =
  [];


for (
  let candidatePosition = 0;
  candidatePosition < result.candidates.length;
  candidatePosition++
) {

  const candidate =
    result.candidates[candidatePosition];


  // ----------------------------------------------------------
  // candidate_index
  // ----------------------------------------------------------

  if (
    !Number.isInteger(
      candidate.candidate_index
    ) ||
    candidate.candidate_index < 0
  ) {
    throw new Error(
      `[Targeted Recheck Evidence Validator] Некорректный candidate_index у кандидата ${candidatePosition}`
    );
  }

  if (
    usedCandidateIndexes.has(
      candidate.candidate_index
    )
  ) {
    throw new Error(
      `[Targeted Recheck Evidence Validator] Повтор candidate_index=${candidate.candidate_index}`
    );
  }

  usedCandidateIndexes.add(
    candidate.candidate_index
  );


  // ----------------------------------------------------------
  // value_text
  // ----------------------------------------------------------

  if (
    typeof candidate.value_text !== 'string' ||
    !candidate.value_text.trim()
  ) {
    throw new Error(
      `[Targeted Recheck Evidence Validator] Пустой value_text у candidate_index=${candidate.candidate_index}`
    );
  }


  // ----------------------------------------------------------
  // status
  // ----------------------------------------------------------

  if (
    !ALLOWED_STATUSES.has(
      candidate.status
    )
  ) {
    throw new Error(
      `[Targeted Recheck Evidence Validator] Недопустимый status=${candidate.status}`
    );
  }


  // ----------------------------------------------------------
  // confidence
  // ----------------------------------------------------------

  if (
    typeof candidate.confidence !== 'number' ||
    !Number.isFinite(candidate.confidence) ||
    candidate.confidence < 0 ||
    candidate.confidence > 1
  ) {
    throw new Error(
      `[Targeted Recheck Evidence Validator] Некорректный confidence=${candidate.confidence}`
    );
  }


  // ----------------------------------------------------------
  // found / requires_review
  // ----------------------------------------------------------

  if (candidate.status === 'found') {

    if (
      candidate.review_reason_code !== null
    ) {
      throw new Error(
        `[Targeted Recheck Evidence Validator] Для found review_reason_code должен быть null`
      );
    }

    if (
      candidate.review_note !== null
    ) {
      throw new Error(
        `[Targeted Recheck Evidence Validator] Для found review_note должен быть null`
      );
    }
  }


  if (
    candidate.status ===
    'requires_review'
  ) {

    if (
      !ALLOWED_REVIEW_CODES.has(
        candidate.review_reason_code
      )
    ) {
      throw new Error(
        `[Targeted Recheck Evidence Validator] Некорректный review_reason_code=${candidate.review_reason_code}`
      );
    }

    if (
      typeof candidate.review_note !== 'string' ||
      !candidate.review_note.trim()
    ) {
      throw new Error(
        '[Targeted Recheck Evidence Validator] Для requires_review нужен review_note'
      );
    }
  }


  // ----------------------------------------------------------
  // evidence
  // ----------------------------------------------------------

  if (
    !Array.isArray(candidate.evidence) ||
    candidate.evidence.length === 0
  ) {
    throw new Error(
      `[Targeted Recheck Evidence Validator] Нет evidence у candidate_index=${candidate.candidate_index}`
    );
  }


  const verifiedEvidence =
    [];


  for (
    let evidenceIndex = 0;
    evidenceIndex < candidate.evidence.length;
    evidenceIndex++
  ) {

    const evidence =
      candidate.evidence[evidenceIndex];

    const evidencePath =
      `candidate[${candidate.candidate_index}].evidence[${evidenceIndex}]`;


    // ========================================================
    // semantic_block evidence
    // ========================================================

    if (
      evidence.source_type ===
      'semantic_block'
    ) {

      if (
        typeof evidence.analysis_unit_id !== 'string' ||
        !evidence.analysis_unit_id
      ) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: нет analysis_unit_id`
        );
      }

      if (
        typeof evidence.semantic_block_id !== 'string' ||
        !evidence.semantic_block_id
      ) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: нет semantic_block_id`
        );
      }

      if (
        typeof evidence.quote !== 'string' ||
        !evidence.quote.trim()
      ) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: quote пуст`
        );
      }


      const blockKey =
        `${evidence.analysis_unit_id}\u0000${evidence.semantic_block_id}`;

      if (!blockMap.has(blockKey)) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: неизвестная пара analysis_unit_id + semantic_block_id`
        );
      }


      const sourceText =
        normalizeWhitespace(
          blockMap.get(blockKey)
        );

      const quote =
        normalizeWhitespace(
          evidence.quote
        );


      if (
        !sourceText.includes(quote)
      ) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: quote отсутствует в semantic block после нормализации пробелов`
        );
      }


      verifiedEvidence.push({
        source_type:
          'semantic_block',

        analysis_unit_id:
          evidence.analysis_unit_id,

        semantic_block_id:
          evidence.semantic_block_id,

        quote:
          evidence.quote,
      });

      continue;
    }


    // ========================================================
    // tender_metadata evidence
    // ========================================================

    if (
      evidence.source_type ===
      'tender_metadata'
    ) {

      if (
        typeof evidence.metadata_key !== 'string' ||
        !evidence.metadata_key
      ) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: нет metadata_key`
        );
      }


      if (
        !Object.prototype.hasOwnProperty.call(
          allowedMetadata,
          evidence.metadata_key
        )
      ) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: неизвестный metadata_key=${evidence.metadata_key}`
        );
      }


      const expectedValue =
        allowedMetadata[
          evidence.metadata_key
        ];

      if (
        JSON.stringify(evidence.value) !==
        JSON.stringify(expectedValue)
      ) {
        throw new Error(
          `[Targeted Recheck Evidence Validator] ${evidencePath}: metadata value не совпадает. Ожидалось ${JSON.stringify(expectedValue)}, получено ${JSON.stringify(evidence.value)}`
        );
      }


      verifiedEvidence.push({
        source_type:
          'tender_metadata',

        metadata_key:
          evidence.metadata_key,

        value:
          evidence.value,
      });

      continue;
    }


    // ========================================================
    // Неизвестный source_type
    // ========================================================

    throw new Error(
      `[Targeted Recheck Evidence Validator] ${evidencePath}: неизвестный source_type=${evidence.source_type}`
    );
  }


  verifiedCandidates.push({
    candidate_index:
      candidate.candidate_index,

    value_text:
      candidate.value_text,

    status:
      candidate.status,

    confidence:
      candidate.confidence,

    evidence:
      verifiedEvidence,

    review_reason_code:
      candidate.review_reason_code,

    review_note:
      candidate.review_note,
  });
}


// ============================================================
// 11. candidate_index должны идти 0..N-1
// ============================================================

const sortedIndexes =
  [...usedCandidateIndexes]
    .sort((a, b) => a - b);

for (
  let index = 0;
  index < sortedIndexes.length;
  index++
) {

  if (sortedIndexes[index] !== index) {
    throw new Error(
      `[Targeted Recheck Evidence Validator] candidate_index должны идти подряд с 0. Получено: ${sortedIndexes.join(', ')}`
    );
  }
}


// ============================================================
// 12. Возвращаем проверенный ответ
// ============================================================

return {
  json: {
    analysis_run_id:
      source.analysis_run_id,

    field_catalog_version:
      source.field_catalog_version,

    field_index:
      source.field_index,

    field_key:
      source.field_key,

    recheck_attempt:
      source.recheck_attempt,

    recheck_outcome:
      result.recheck_outcome,

    candidates:
      verifiedCandidates,

    recheck_note:
      result.recheck_note ?? null,

    original_aggregation:
      source.original_aggregation,

    existing_candidates:
      source.existing_candidates,

    recheck_context:
      source.recheck_context,

    targeted_recheck_meta: {
      response_id:
        aiResponse.id ?? null,

      model:
        aiResponse.model ?? null,

      finish_reason:
        choice.finish_reason,

      usage:
        aiResponse.usage ?? null,
    },

    evidence_validated:
      true,
  },
};

const input = $json;


// ============================================================
// 1. Проверки входа
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Подготовить запрос Validator Targeted Recheck] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Подготовить запрос Validator Targeted Recheck] Нет field_key'
  );
}

if (input.evidence_validated !== true) {
  throw new Error(
    '[Подготовить запрос Validator Targeted Recheck] evidence ещё не прошёл детерминированную проверку'
  );
}

if (!Array.isArray(input.candidates)) {
  throw new Error(
    '[Подготовить запрос Validator Targeted Recheck] candidates должен быть массивом'
  );
}


// ============================================================
// 2. Пока валидируем только nm_price_with_vat
// ============================================================

if (input.field_key !== 'nm_price_with_vat') {
  throw new Error(
    `[Подготовить запрос Validator Targeted Recheck] Пока не поддерживается field_key=${input.field_key}`
  );
}


// ============================================================
// 3. Компактно собираем исходный контекст
// ============================================================

const contextIndex = [];

for (const unit of input.recheck_context ?? []) {

  for (const segment of unit.segments ?? []) {

    contextIndex.push({
      analysis_unit_id:
        unit.analysis_unit_id,

      document: {
        document_id:
          unit.document?.document_id ?? null,

        document_index:
          unit.document?.document_index ?? null,

        file_name:
          unit.document?.file_name ?? null,
      },

      section_title:
        unit.section_title ?? null,

      semantic_block_id:
        segment.semantic_block_id,

      text:
        segment.text ?? '',
    });
  }
}


// ============================================================
// 4. System Prompt
// ============================================================

const systemPrompt = `
Ты — независимый AI Validator системы анализа тендерной документации.

Перед тобой находится результат Targeted Recheck Extractor.

Extractor уже:
- повторно проанализировал релевантный контекст;
- сформировал candidate facts;
- указал evidence.

Детерминированная система УЖЕ проверила:
- что analysis_unit_id существуют;
- что semantic_block_id существуют;
- что цитаты действительно находятся в этих semantic blocks;
- что значения tender_metadata совпадают с исходными metadata.

Поэтому твоя задача НЕ проверять существование цитат.

Твоя задача — проверить ЛОГИЧЕСКУЮ ОБОСНОВАННОСТЬ каждого candidate.


ЦЕЛЕВОЕ ПОЛЕ:

nm_price_with_vat

Оно должно содержать:
1. размер начальной максимальной цены закупки / контракта;
2. сведения об НДС, только если они действительно подтверждены.


ВАЖНЫЕ ПРАВИЛА:

1. Не подтверждай candidate только потому, что evidence технически существует.

2. Различай:
- цена отдельной позиции;
- сумма спецификации;
- цена договора;
- начальная максимальная цена закупки.

Это разные понятия.

3. tender_metadata.max_price является самостоятельным структурированным
источником максимальной цены закупки.

4. Если tender_metadata.max_price = X,
а официальный документ той же закупки содержит итоговую сумму X,
это может быть сильным взаимным подтверждением.

5. Однако простого числового совпадения недостаточно:
нужно оценить смысл источников и контекст.

6. Сведения об НДС должны иметь отдельное подтверждение.

Например:

"Сумма, руб (в т.ч. НДС)"

явно подтверждает, что соответствующая сумма включает НДС.

7. Пустое поле:

"Цена договора составляет __________"

не подтверждает никакой конкретной суммы.

8. Значения из:
- штрафов;
- пеней;
- процентов;
- пороговых значений;
- примеров расчётов

не являются ценой закупки.

9. Не используй внешние знания.

10. Не исправляй candidate и не извлекай новый.
Ты только оцениваешь переданный candidate.

11. Если candidate полностью подтверждён —
verdict="confirmed".

12. Если candidate правдоподобен, но остаётся существенный логический разрыв —
verdict="requires_review".

13. Если evidence противоречит candidate или candidate сделан
из нерелевантных данных —
verdict="rejected".

14. Верни только валидный JSON.


Допустимые verdict:

confirmed
requires_review
rejected


Допустимые reason_code:

insufficient_evidence
ambiguous_scope
unsupported_inference
conflicting_evidence
wrong_field
irrelevant_evidence
other
null


ФОРМАТ ОТВЕТА:

{
  "schema_version": "targeted_recheck_validator_v1",
  "field_key": "nm_price_with_vat",
  "validations": [
    {
      "candidate_index": 0,
      "verdict": "confirmed",
      "confidence": 0.95,
      "reason_code": null,
      "reason_note": "краткое объяснение"
    }
  ]
}

Если verdict="confirmed":
- reason_code должен быть null;
- reason_note должен объяснить, почему логическая связь достаточна.

Если verdict="requires_review":
- reason_code не должен быть null;
- reason_note должен описать, чего именно не хватает.

Если verdict="rejected":
- reason_code не должен быть null;
- reason_note должен объяснить ошибку вывода.

Каждый входной candidate должен получить РОВНО ОДНУ validation.
`.trim();


// ============================================================
// 5. User Prompt
// ============================================================

const userPrompt = `
ПРОВЕРЬ РЕЗУЛЬТАТ TARGETED RECHECK

field_key:
${input.field_key}


ИСХОДНАЯ ПРОБЛЕМА:

${JSON.stringify(
  input.original_aggregation,
  null,
  2
)}


КАНДИДАТЫ ПОСЛЕ TARGETED RECHECK:

${JSON.stringify(
  input.candidates,
  null,
  2
)}


КОНТЕКСТ, ИЗ КОТОРОГО БЫЛИ ВЗЯТЫ EVIDENCE:

${JSON.stringify(
  contextIndex,
  null,
  2
)}


Проверь только логическую обоснованность candidates.

Не извлекай новые значения.

Особенно проверь:

1. Достаточно ли tender_metadata.max_price=85000,
чтобы связать число 85000 с максимальной ценой закупки.

2. Достаточно ли таблицы спецификации,
где сумма 85000 указана в колонке
"Сумма, руб (в т.ч. НДС)",
чтобы подтвердить НДС.

3. Не происходит ли недопустимой подмены
"сумма спецификации" → "НМЦК".

Верни строго targeted_recheck_validator_v1.
`.trim();


// ============================================================
// 6. Output
// ============================================================

return {
  json: {
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,

    recheck_attempt:
      input.recheck_attempt,

    candidates:
      input.candidates,

    candidates_count:
