parameters.jsCode:
const aiResponse = $json;

const source =
  $('Подготовить запрос Validator Targeted Recheck').item.json;


// ============================================================
// 1. Проверяем HTTP / DeepSeek response
// ============================================================

const choice =
  aiResponse?.choices?.[0];

if (!choice) {
  throw new Error(
    '[Validator Targeted Recheck] Нет choices[0]'
  );
}

if (choice.finish_reason !== 'stop') {
  throw new Error(
    `[Validator Targeted Recheck] Некорректный finish_reason=${choice.finish_reason}`
  );
}

const content =
  choice?.message?.content;

if (
  typeof content !== 'string' ||
  !content.trim()
) {
  throw new Error(
    '[Validator Targeted Recheck] message.content пуст'
  );
}


// ============================================================
// 2. Парсим JSON
// ============================================================

let result;

try {
  result =
    JSON.parse(content);
} catch (error) {
  throw new Error(
    `[Validator Targeted Recheck] Невалидный JSON: ${error.message}`
  );
}


// ============================================================
// 3. Разрешённые значения
// ============================================================

const ALLOWED_VERDICTS =
  new Set([
    'confirmed',
    'requires_review',
    'rejected',
  ]);

const ALLOWED_REASON_CODES =
  new Set([
    'insufficient_evidence',
    'ambiguous_scope',
    'unsupported_inference',
    'conflicting_evidence',
    'wrong_field',
    'irrelevant_evidence',
    'other',
  ]);


// ============================================================
// 4. Проверяем общий контракт
// ============================================================

if (
  result.schema_version !==
  'targeted_recheck_validator_v1'
) {
  throw new Error(
    `[Validator Targeted Recheck] Некорректный schema_version=${result.schema_version}`
  );
}

if (
  result.field_key !==
  source.field_key
) {
  throw new Error(
    `[Validator Targeted Recheck] field_key изменён: ожидался ${source.field_key}, получен ${result.field_key}`
  );
}

if (!Array.isArray(result.validations)) {
  throw new Error(
    '[Validator Targeted Recheck] validations должен быть массивом'
  );
}


// ============================================================
// 5. Проверяем количество validations
// ============================================================

const expectedIndexes =
  Array.isArray(source.allowed_candidate_indexes)
    ? source.allowed_candidate_indexes
    : [];

if (
  result.validations.length !==
  expectedIndexes.length
) {
  throw new Error(
    `[Validator Targeted Recheck] Неверное количество validations. Ожидалось ${expectedIndexes.length}, получено ${result.validations.length}`
  );
}


// ============================================================
// 6. Проверяем каждую validation
// ============================================================

const expectedIndexSet =
  new Set(expectedIndexes);

const usedIndexes =
  new Set();

const validationMap =
  new Map();


for (
  let position = 0;
  position < result.validations.length;
  position++
) {

  const validation =
    result.validations[position];


  // ----------------------------------------------------------
  // candidate_index
  // ----------------------------------------------------------

  if (
    !Number.isInteger(
      validation.candidate_index
    )
  ) {
    throw new Error(
      `[Validator Targeted Recheck] candidate_index не integer в validation ${position}`
    );
  }

  if (
    !expectedIndexSet.has(
      validation.candidate_index
    )
  ) {
    throw new Error(
      `[Validator Targeted Recheck] Неизвестный candidate_index=${validation.candidate_index}`
    );
  }

  if (
    usedIndexes.has(
      validation.candidate_index
    )
  ) {
    throw new Error(
      `[Validator Targeted Recheck] Повтор candidate_index=${validation.candidate_index}`
    );
  }

  usedIndexes.add(
    validation.candidate_index
  );


  // ----------------------------------------------------------
  // verdict
  // ----------------------------------------------------------

  if (
    !ALLOWED_VERDICTS.has(
      validation.verdict
    )
  ) {
    throw new Error(
      `[Validator Targeted Recheck] Недопустимый verdict=${validation.verdict}`
    );
  }


  // ----------------------------------------------------------
  // confidence
  // ----------------------------------------------------------

  if (
    typeof validation.confidence !== 'number' ||
    !Number.isFinite(validation.confidence) ||
    validation.confidence < 0 ||
    validation.confidence > 1
  ) {
    throw new Error(
      `[Validator Targeted Recheck] Некорректный confidence=${validation.confidence}`
    );
  }


  // ----------------------------------------------------------
  // reason_note
  // ----------------------------------------------------------

  if (
    typeof validation.reason_note !== 'string' ||
    !validation.reason_note.trim()
  ) {
    throw new Error(
      `[Validator Targeted Recheck] reason_note обязателен для candidate_index=${validation.candidate_index}`
    );
  }


  // ----------------------------------------------------------
  // confirmed
  // ----------------------------------------------------------

  if (
    validation.verdict ===
    'confirmed'
  ) {

    if (
      validation.reason_code !== null
    ) {
      throw new Error(
        `[Validator Targeted Recheck] Для confirmed reason_code должен быть null`
      );
    }
  }


  // ----------------------------------------------------------
  // requires_review / rejected
  // ----------------------------------------------------------

  if (
    validation.verdict ===
      'requires_review' ||
    validation.verdict ===
      'rejected'
  ) {

    if (
      !ALLOWED_REASON_CODES.has(
        validation.reason_code
      )
    ) {
      throw new Error(
        `[Validator Targeted Recheck] Некорректный reason_code=${validation.reason_code}`
      );
    }
  }


  validationMap.set(
    validation.candidate_index,
    {
      verdict:
        validation.verdict,

      confidence:
        validation.confidence,

      reason_code:
        validation.reason_code,

      reason_note:
        validation.reason_note,
    }
  );
}


// ============================================================
// 7. Проверяем, что ни один candidate не пропущен
// ============================================================

for (const candidateIndex of expectedIndexes) {

  if (!usedIndexes.has(candidateIndex)) {
    throw new Error(
      `[Validator Targeted Recheck] Нет validation для candidate_index=${candidateIndex}`
    );
  }
}


// ============================================================
// 8. Соединяем candidate + validation
// ============================================================

const validatedCandidates =
  source.candidates.map(candidate => {

    const validation =
      validationMap.get(
        candidate.candidate_index
      );

    if (!validation) {
      throw new Error(
        `[Validator Targeted Recheck] Не найдена validation для candidate_index=${candidate.candidate_index}`
      );
    }

    return {
      ...candidate,

      validator_verdict:
        validation.verdict,

      validator_confidence:
        validation.confidence,

      validator_reason_code:
        validation.reason_code,

      validator_reason_note:
        validation.reason_note,
    };
  });


// ============================================================
// 9. Статистика результата
// ============================================================

const confirmedCount =
  validatedCandidates.filter(
    candidate =>
      candidate.validator_verdict ===
      'confirmed'
  ).length;

const requiresReviewCount =
  validatedCandidates.filter(
    candidate =>
      candidate.validator_verdict ===
      'requires_review'
  ).length;

const rejectedCount =
  validatedCandidates.filter(
    candidate =>
      candidate.validator_verdict ===
      'rejected'
  ).length;


// ============================================================
// 10. Output
// ============================================================

return {
  json: {
    analysis_run_id:
      source.analysis_run_id,

    field_catalog_version:
      source.field_catalog_version,

    field_index:
      source.field_index,

    field_key:
      source.field_key,

    recheck_attempt:
      source.recheck_attempt,

    validated_candidates:
      validatedCandidates,

    validation_stats: {
      total:
        validatedCandidates.length,

      confirmed:
        confirmedCount,

      requires_review:
        requiresReviewCount,

      rejected:
        rejectedCount,
    },

    targeted_recheck_validator_meta: {
      response_id:
        aiResponse.id ?? null,

      model:
        aiResponse.model ?? null,

      finish_reason:
        choice.finish_reason,

      usage:
        aiResponse.usage ?? null,
    },

    original_aggregation:
      source.original_aggregation,

    existing_candidates:
      source.existing_candidates,

    recheck_context:
      source.recheck_context,

    validator_response_validated:
      true,
  },
};

const input = $json;


// ============================================================
// 1. Проверяем вход
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Собрать кандидаты после Targeted Recheck] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Собрать кандидаты после Targeted Recheck] Нет field_key'
  );
}

if (
  input.validator_response_validated !== true
) {
  throw new Error(
    '[Собрать кандидаты после Targeted Recheck] Ответ Validator ещё не проверен'
  );
}


// ============================================================
// 2. Старые кандидаты первого прохода
// ============================================================

const existingCandidates =
  Array.isArray(input.existing_candidates)
    ? input.existing_candidates
    : [];

const normalizedExisting =
  existingCandidates.map(candidate => ({
    candidate_ref:
      `fact:${candidate.fact_id}`,

    origin:
      'initial_analysis',

    fact_id:
      candidate.fact_id,

    recheck_candidate_id:
      null,

    value_text:
      candidate.value_text,

    validator_verdict:
      candidate.validator_verdict,

    validator_confidence:
      candidate.validator_confidence,

    validator_reason_code:
      candidate.validator_reason_code,

    validator_reason_note:
      candidate.validator_reason_note,

    document:
      candidate.document ?? null,

    analysis_unit_id:
      candidate.analysis_unit_id ?? null,

    evidence:
      Array.isArray(candidate.evidence)
        ? candidate.evidence
        : [],

    recheck_attempt:
      null,
  }));


// ============================================================
// 3. Новые кандидаты Targeted Recheck
//
// rejected дальше в Semantic Aggregator не передаём,
// как и в основном aggregation pipeline.
// ============================================================

const validatedRecheckCandidates =
  Array.isArray(input.validated_candidates)
    ? input.validated_candidates
    : [];

const normalizedRecheck =
  validatedRecheckCandidates

    .filter(candidate =>
      candidate.validator_verdict === 'confirmed' ||
      candidate.validator_verdict === 'requires_review'
    )

    .map(candidate => ({
      candidate_ref:
        `recheck:${input.recheck_attempt}:${candidate.candidate_index}`,

      origin:
        'targeted_recheck',

      fact_id:
        null,

      recheck_candidate_id:
        `recheck:${input.recheck_attempt}:${candidate.candidate_index}`,

      value_text:
        candidate.value_text,

      validator_verdict:
        candidate.validator_verdict,

      validator_confidence:
        candidate.validator_confidence,

      validator_reason_code:
        candidate.validator_reason_code,

      validator_reason_note:
        candidate.validator_reason_note,

      document:
        null,

      analysis_unit_id:
        null,

      evidence:
        Array.isArray(candidate.evidence)
          ? candidate.evidence
          : [],

      recheck_attempt:
        input.recheck_attempt,
    }));


// ============================================================
// 4. Объединяем
// ============================================================

const candidates =
  [
    ...normalizedExisting,
    ...normalizedRecheck,
  ];


// ============================================================
// 5. Статистика
// ============================================================

const confirmedCount =
  candidates.filter(candidate =>
    candidate.validator_verdict === 'confirmed'
  ).length;

const requiresReviewCount =
  candidates.filter(candidate =>
    candidate.validator_verdict === 'requires_review'
  ).length;


// ============================================================
// 6. Output
// ============================================================

return {
  json: {
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,

    aggregation_round:
      2,

    recheck_attempt:
      input.recheck_attempt,

    candidates,

    candidates_count:
      candidates.length,

    candidate_stats: {
      confirmed:
        confirmedCount,

      requires_review:
        requiresReviewCount,
    },

    original_aggregation:
      input.original_aggregation,

    targeted_recheck_completed:
      true,
  },
};

