parameters.jsCode:
const input = $json;


// ============================================================
// 1. Проверяем вход
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[Metadata Resolver] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[Metadata Resolver] Нет field_key'
  );
}


// ============================================================
// 2. Получаем tender_meta один раз из Aggregator
// ============================================================

let tenderMeta =
  $('Загрузить факты закупки')
    .first()
    .json
    .tender_meta ?? null;


// На случай если Postgres когда-нибудь вернёт JSON строкой.
if (typeof tenderMeta === 'string') {

  try {
    tenderMeta =
      JSON.parse(tenderMeta);
  } catch {
    throw new Error(
      '[Metadata Resolver] tender_meta является строкой, но невалидным JSON'
    );
  }
}


if (
  !tenderMeta ||
  typeof tenderMeta !== 'object'
) {
  throw new Error(
    '[Metadata Resolver] tender_meta отсутствует'
  );
}


// ============================================================
// 3. Результат по умолчанию
//
// Очень важно:
// отсутствие правила здесь НЕ означает not_found.
// Оно означает:
// "Metadata Resolver не смог закрыть поле,
// передай его дальше в Targeted Recheck".
// ============================================================

let metadataResolved =
  false;

let finalValueText =
  null;

let metadataEvidence =
  [];


// ============================================================
// 4. PLATFORM
//
// Это строгое детерминированное соответствие:
//
// field_key = platform
// ↓
// tender_meta.platform
//
// Никакой AI здесь не нужен.
// ============================================================

if (input.field_key === 'platform') {

  const platform =
    tenderMeta.platform;


  if (
    platform &&
    typeof platform === 'object'
  ) {

    const name =
      typeof platform.name === 'string'
        ? platform.name.trim()
        : '';

    const url =
      typeof platform.url === 'string'
        ? platform.url.trim()
        : '';


    // Для финального текстового поля приоритетно
    // используем название площадки.
    //
    // URL сохраняем в provenance отдельно.
    if (name || url) {

      metadataResolved =
        true;

      finalValueText =
        name || url;

      metadataEvidence = [
        {
          source_type:
            'tender_metadata',

          metadata_key:
            'platform',

          value:
            platform,
        },
      ];
    }
  }
}


// ============================================================
// APPLICATION DEADLINE
// ============================================================

if (
  input.field_key === 'application_deadline' &&
  !metadataResolved
) {

  const submissionCloseAt =
    tenderMeta.submission_close_at;

  if (
    typeof submissionCloseAt === 'string' &&
    submissionCloseAt.trim()
  ) {

    metadataResolved =
      true;

    finalValueText =
      submissionCloseAt.trim();

    metadataEvidence = [
      {
        source_type:
          'tender_metadata',

        metadata_key:
          'submission_close_at',

        value:
          submissionCloseAt,
      },
    ];
  }
}

// ============================================================
// PROCUREMENT SUBJECT
// ============================================================

if (
  input.field_key === 'procurement_subject' &&
  !metadataResolved
) {

  const title =
    tenderMeta.title;

  if (
    typeof title === 'string' &&
    title.trim()
  ) {

    metadataResolved =
      true;

    finalValueText =
      title.trim();

    metadataEvidence = [
      {
        source_type:
          'tender_metadata',

        metadata_key:
          'title',

        value:
          title,
      },
    ];
  }
}


// ============================================================
// CUSTOMER
// ============================================================

if (
  input.field_key === 'customer' &&
  !metadataResolved
) {

  const primaryCustomer =
    tenderMeta.primary_customer;

  if (
    primaryCustomer &&
    typeof primaryCustomer === 'object' &&
    typeof primaryCustomer.name === 'string' &&
    primaryCustomer.name.trim()
  ) {

    metadataResolved =
      true;

    finalValueText =
      primaryCustomer.name.trim();

    metadataEvidence = [
      {
        source_type:
          'tender_metadata',

        metadata_key:
          'primary_customer',

        value:
          primaryCustomer,
      },
    ];
  }
}

// ============================================================
// 5. Возвращаем унифицированный результат
// ============================================================

return {
  json: {

    // Исходная идентификация поля
    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,


    // Было ли поле закрыто Metadata Resolver
    metadata_resolved:
      metadataResolved,


    // Если resolved — это уже готовый результат поля.
    // Если false — поле уйдёт дальше в Targeted Recheck.
    aggregation_status:
      metadataResolved
        ? 'resolved'
        : null,

    final_value_text:
      finalValueText,

    confidence:
      metadataResolved
        ? 1
        : null,


    // Откуда взялось значение
    resolution_method:
      metadataResolved
        ? 'deterministic_metadata'
        : null,

    evidence:
      metadataEvidence,


    // Сохраняем исходный grouped field,
    // чтобы следующая ветка ничего не потеряла.
    original_field:
      input,
  },
};

const input = $json;


// ============================================================
// 1. Базовые проверки
// ============================================================

if (!input.analysis_run_id) {
  throw new Error(
    '[not_found Finalizer] Нет analysis_run_id'
  );
}

if (!input.field_key) {
  throw new Error(
    '[not_found Finalizer] Нет field_key'
  );
}


// ============================================================
// 2. not_found допустим только для сценария,
// где первоначально вообще не было candidates
// ============================================================

if (
  input.original_aggregation?.status !==
  'no_initial_candidates'
) {
  throw new Error(
    '[not_found Finalizer] not_found допустим только после no_initial_candidates'
  );
}


const existingCandidates =
  Array.isArray(input.existing_candidates)
    ? input.existing_candidates
    : [];


if (existingCandidates.length > 0) {
  throw new Error(
    '[not_found Finalizer] Найдены existing_candidates — нельзя ставить not_found'
  );
}


// ============================================================
// 3. Определяем, КАК именно мы пришли к not_found
//
// A.
// Targeted retrieval вообще не нашёл контекст.
//
// B.
// Контекст нашли, AI Recheck его проверил,
// но доказательств целевого поля оказалось недостаточно.
// ============================================================

const noContext =
  input.context_found === false;

const insufficientAfterAi =
  input.evidence_validated === true &&
  input.recheck_outcome === 'insufficient_evidence' &&
  Array.isArray(input.candidates) &&
  input.candidates.length === 0;


if (!noContext && !insufficientAfterAi) {
  throw new Error(
    '[not_found Finalizer] Вход не соответствует допустимому сценарию not_found'
  );
}


// ============================================================
// 4. Причина результата
// ============================================================

let notFoundReasonCode;
let notFoundNote;
let resolutionMethod;


if (noContext) {

  notFoundReasonCode =
    'no_relevant_context_after_targeted_retrieval';

  notFoundNote =
    'Первичный анализ не сформировал кандидатов, structured TenderMeta не закрыл поле, а Targeted Recheck не нашёл релевантного контекста в предоставленных документах.';

  resolutionMethod =
    'targeted_recheck_no_context';

}
else {

  notFoundReasonCode =
    'insufficient_evidence_after_targeted_recheck';

  notFoundNote =
    input.recheck_note ??
    'Targeted Recheck нашёл и проверил релевантный контекст, но в предоставленных источниках оказалось недостаточно доказательств для определения значения целевого поля.';

  resolutionMethod =
    'targeted_recheck_insufficient_evidence';

}


// ============================================================
// 5. Финальный результат
//
// ВАЖНО:
// not_found не означает:
//
// "нет"
// "не требуется"
// "не предусмотрено"
//
// Он означает:
//
// "в предоставленных источниках значение поля
// надёжно не установлено после полного анализа"
// ============================================================

return {
  json: {

    analysis_run_id:
      input.analysis_run_id,

    field_catalog_version:
      input.field_catalog_version,

    field_index:
      input.field_index,

    field_key:
      input.field_key,


    aggregation_status:
      'not_found',

    final_value_text:
      null,

    confidence:
      null,

    needs_recheck:
      false,

    aggregation_validated:
      true,


    resolution_method:
      resolutionMethod,

    not_found_scope:
      'provided_sources',

    not_found_reason_code:
      notFoundReasonCode,

    not_found_note:
      notFoundNote,


    evidence:
      [],


    recheck_attempt:
      input.recheck_attempt ?? null,

    recheck_profile:
      input.recheck_profile ?? null,

    original_aggregation:
      input.original_aggregation ?? null,


    targeted_recheck_result: {
      context_found:
        input.context_found ?? true,

      recheck_outcome:
        input.recheck_outcome ?? null,

      recheck_note:
        input.recheck_note ?? null,

      evidence_validated:
        input.evidence_validated ?? null,
    },
  },
};

const input = $json;

if (
  !Array.isArray(input.candidates) ||
  input.candidates.length === 0
) {
  throw new Error(
    '[TEST confirmed] Нет candidates'
  );
}

