if (items.length === 0) {
  throw new Error(
    '[Подготовить вызов Finalizer] FINAL UPSERT не вернул ни одной строки'
  );
}

const runIds = [
  ...new Set(
    items
      .map(item => item.json.analysis_run_id)
      .filter(Boolean)
  ),
];

if (runIds.length !== 1) {
  throw new Error(
    `[Подготовить вызов Finalizer] Ожидался один analysis_run_id, получено: ${JSON.stringify(runIds)}`
  );
}

const fieldKeys = items
  .map(item => item.json.field_key)
  .filter(Boolean);

return [
  {
    json: {
      analysis_run_id: runIds[0],
      trigger_source: 'aggregator',
      trigger_field_keys: fieldKeys,
    },
  },
];
